/* Installation guidance is local to this browser; it never stores account data. */
(function(){
'use strict';
const key='neo-install-guide-v1',ua=navigator.userAgent||'',ios=/iPhone|iPad|iPod/.test(ua)||(/Macintosh/.test(ua)&&navigator.maxTouchPoints>1),android=/Android/.test(ua),embedded=/FBAN|FBAV|Instagram|; wv|MicroMessenger|TikTok/.test(ua);
const browser=/CriOS/.test(ua)?'Chrome':/FxiOS|Firefox/.test(ua)?'Firefox':/EdgiOS|Edg\//.test(ua)?'Edge':/SamsungBrowser/.test(ua)?'Samsung Internet':/OPR\//.test(ua)?'Opera':/Chrome/.test(ua)?'Chrome':ios?'Safari':'seu navegador';
const installed=()=>navigator.standalone===true||['standalone','fullscreen','minimal-ui'].some(m=>window.matchMedia?.('(display-mode: '+m+')').matches);
let seen=false,pending=null,prompting=false,handoff=false,handoffDismissed=false;
try{seen=localStorage.getItem(key)==='done';}catch{}
const callback=/[?&](code|token_hash|error)=/.test(location.search||'')||/access_token=|type=recovery|error=/.test(location.hash||'');
let recovery=false;try{recovery=!!sessionStorage.getItem('neo-recovery-request');}catch{}
const api={blocking:!seen&&!installed()&&!callback&&!recovery&&location.protocol!=='file:',guide,screen,loginNotice};window.NeoInstall=api;
function mark(){seen=true;try{localStorage.setItem(key,'done');}catch{}}
function finish(){handoffDismissed=true;handoff=false;mark();api.blocking=false;window.dispatchEvent(new Event('neo-install-continue'));}
function showHandoff(){if(handoffDismissed||installed())return;mark();handoff=true;api.blocking=true;window.dispatchEvent(new Event('neo-install-continue'));}
function symbol(type){const paths={share:'<path d="M12 16V3m-5 5 5-5 5 5M5 13v8h14v-8"/>',menu:'<circle cx="12" cy="5" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="12" cy="19" r="1"/>',home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M9 16h6m-3-3v6"/>',check:'<path d="m5 12 4 4L19 6"/>'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[type]+'</svg>';}
function steps(){
 if(embedded)return [['menu','Abra no navegador','No menu desta janela, escolha abrir no Safari ou Chrome. Depois acesse este mesmo link.'],['home','Adicione à tela inicial','No navegador, abra esta orientação novamente para ver os passos do seu aparelho.']];
 if(ios&&['Safari','Chrome'].includes(browser))return [['share','Toque em Compartilhar',browser==='Chrome'?'Procure o ícone de compartilhar à direita da barra de endereço.':'Procure o quadrado com a seta para cima. Dependendo da versão, ele fica dentro do menu … .'],['home','Adicionar à Tela de Início','Se a opção não aparecer de imediato, role a lista de ações.'],['check','Confirme em Adicionar','Se aparecer “Abrir como App da Web”, deixe ativado. Depois abra pelo novo ícone na sua tela inicial.']];
 if(ios)return [['share','Abra este link no Safari','Copie o endereço desta página e abra no Safari para adicionar o aplicativo.'],['home','Compartilhar → Adicionar à Tela de Início','Confirme em Adicionar e abra pelo novo ícone.']];
 if(android)return [['menu','Abra o menu do '+browser,'Toque em ⋮ ou no menu do navegador.'],['home','Escolha Instalar','Pode aparecer como “Instalar e criar atalho”, “Instalar aplicativo” ou “Adicionar à tela inicial”.'],['check','Confirme e abra pelo ícone','Se a opção não aparecer, tente abrir este link no Chrome.']];
 return [['menu','Abra o menu do navegador','No Chrome ou Edge, procure a opção de instalar este site como aplicativo.'],['home','Confirme a instalação','Se a opção não estiver disponível, você pode continuar usando o navegador.']];
}
function guide(){return `<div class="install-guide"><p class="install-device">${ios?'iPhone / iPad':android?'Android':'Computador'} · ${embedded?'navegador dentro de outro aplicativo':browser}</p><button type="button" class="primary full" data-install-native ${pending?'':'hidden'}>${symbol('home')} Instalar aplicativo</button><p class="sub" data-install-native-help ${pending?'':'hidden'}>Confirme a instalação na janela do navegador.</p><ol class="install-steps">${steps().map(([i,title,desc])=>`<li><span class="install-step-icon">${symbol(i)}</span><div><strong>${title}</strong><p>${desc}</p></div></li>`).join('')}</ol><p class="sub" data-install-status role="status">${installed()?'Você já está usando o aplicativo instalado.':'Não precisa procurar na loja de aplicativos.'}</p></div>`;}
function loginNotice(){if(installed()||location.protocol==='file:')return '';return `<aside class="install-login-notice"><strong>Ainda não tem o aplicativo?</strong><p>Instale para abrir direto pelo ícone. Se já instalou, procure NeoPeptídeos na tela inicial ou no menu de aplicativos.</p><details><summary>Instalar aplicativo</summary>${guide()}</details></aside>`;}
function screen(){if(handoff)return `<section class="card install-welcome" aria-labelledby="installTitle"><img class="install-logo" src="assets/apple-touch-icon.png" alt="Ícone do NeoPeptídeos"><p class="eyebrow">PRÓXIMO PASSO</p><h1 id="installTitle">Agora abra pelo ícone.</h1><p class="sub">A instalação foi confirmada. Pode levar alguns instantes para o ícone aparecer.</p><ol class="install-steps"><li><span class="install-step-icon">${symbol('home')}</span><div><strong>Volte à tela inicial</strong><p>Procure o NeoPeptídeos na tela inicial ou no menu de aplicativos do seu aparelho.</p></div></li><li><span class="install-step-icon">${symbol('check')}</span><div><strong>Toque no ícone do aplicativo</strong><p>Entre ou crie sua conta por lá para continuar.</p></div></li></ol><p class="sub">Você já pode fechar esta aba do navegador.</p><button type="button" class="text-btn full space" data-install-continue>Prefiro continuar no navegador</button></section>`;return `<section class="card install-welcome" aria-labelledby="installTitle"><img class="install-logo" src="assets/apple-touch-icon.png" alt=""><p class="eyebrow">NEOPEPTÍDEOS SEMPRE À MÃO</p><h1 id="installTitle">Comece pela sua tela inicial.</h1><p class="sub">Adicione o aplicativo para abrir direto pelo ícone, sempre que precisar.</p>${guide()}<button type="button" class="secondary full" data-install-continue>Continuar no navegador</button><p class="install-footnote">Esta orientação aparece na primeira visita neste navegador. Você pode consultá-la depois em Perfil → Instalar aplicativo.</p></section>`;}
function refresh(){document.querySelectorAll('[data-install-native],[data-install-native-help]').forEach(el=>el.hidden=!pending);}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();pending=e;refresh();});
window.addEventListener('appinstalled',()=>{pending=null;if(api.blocking||prompting||handoff)showHandoff();});
document.addEventListener('click',async e=>{
 if(e.target.closest('[data-install-continue]')){finish();return;}
 if(!e.target.closest('[data-install-native]')||!pending||prompting)return;
 const event=pending;pending=null;prompting=true;handoffDismissed=false;refresh();
 try{await event.prompt();const choice=await event.userChoice;if(choice.outcome==='accepted'){showHandoff();return;}document.querySelectorAll('[data-install-status]').forEach(el=>el.textContent='Você pode seguir os passos acima ou continuar no navegador.');}catch{document.querySelectorAll('[data-install-status]').forEach(el=>el.textContent='Use os passos acima para adicionar o aplicativo.');}finally{prompting=false;}
});
if(installed())mark();
})();
